const minAspectRatio = 1.5
const minWidth = 1280

function isUsableBackground(image):
    return image.imageId is not empty
        and image.alphaChannel is false
        and image.width >= minWidth
        and image.height > 0
        and image.width / image.height >= minAspectRatio

function backgroundURL(game):
    artwork = first(game.artworks where isUsableBackground)
    if artwork exists:
        return igdbImageURL("1080p", artwork.imageId)

    screenshot = first(game.screenshots where isUsableBackground)
    if screenshot exists:
        return igdbImageURL("1080p", screenshot.imageId)

    return "" // frontend renders its neutral fallback

function igdbImageURL(size, imageId):
    return "https://images.igdb.com/igdb/image/upload/t_"
        + size + "/" + imageId + ".jpg"

// Cover URL remains independent:
coverURL = igdbImageURL("cover_big_2x", game.cover.imageId)

